script:
(function () {
  'use strict';
  // Retirement drawdown. Income W is withdrawn at the start of each month and rises by g once a
  // year; the rest earns i = (1 + annual return)^(1/12) - 1 a month. With v = 1 / (1 + i):
  //   savings needed S = W x a x sum over y < N of ((1 + g) x v^12)^y + legacy x v^(12N)
  // where a = (1 - v^12) / (1 - v) is the value of 12 monthly payments made at the start of each
  // month (a = 12 when i = 0). Income mode solves for W, needed mode for S, the return mode
  // solves for the return by bisection, and the "how long" mode runs the balance month by month.
  // CHECKS (Node, scratch tests): 0% return, 0% increase: $600,000 over 30 years = $1,666.67 a
  // month; at 5% with no increase the payment matches the annuity-due formula
  // W = S x i / ((1 - (1 + i)^-360) x (1 + i)) = $3,167.43 for $600,000; the month-by-month run
  // with the solved income ends at $0 (or at the legacy amount); solving for the return with
  // the income from a 5% run returns 5.0%; $600,000 at $3,000 a month and 0% lasts 16.7 years.
  function monthlyRate(r) { return Math.pow(1 + r, 1 / 12) - 1; }

  // Value at retirement of $1 a month (first year), rising g a year, for N years at return r.
  function factor(r, g, N) {
    var i = monthlyRate(r), v = 1 / (1 + i), a = i === 0 ? 12 : (1 - Math.pow(v, 12)) / (1 - v);
    var q = (1 + g) * Math.pow(v, 12), s = 0;
    for (var y = 0; y < N; y++) s += Math.pow(q, y);
    return a * s;
  }
  function legacyPv(L, r, N) { return L * Math.pow(1 + r, -N); }

  // Month-by-month run; stops when the money runs out or after maxYears.
  function run(S, W, r, g, maxYears) {
    var i = monthlyRate(r), bal = S, rows = [], total = 0, months = null;
    for (var y = 0; y < maxYears; y++) {
      var pay = W * Math.pow(1 + g, y), out = 0, growth = 0;
      for (var m = 0; m < 12; m++) {
        if (pay > bal + 1e-6) { if (months === null) months = y * 12 + m + (pay > 0 ? bal / pay : 0); out += bal; bal = 0; break; }
        bal -= pay; out += pay;
        var gr = bal * i; growth += gr; bal += gr;
      }
      total += out;
      rows.push({ year: y + 1, pay: pay, out: out, growth: growth, balance: bal });
      if (months !== null) break;
    }
    return { rows: rows, total: total, months: months, end: bal };
  }

  function solveRate(S, W, g, N, L) {
    var f = function (r) { return W * factor(r, g, N) + legacyPv(L, r, N) - S; };
    var lo = -0.5, hi = 1;
    if (f(hi) > 0) return { rate: null, high: true };
    if (f(lo) < 0) return { rate: null, high: false };
    for (var k = 0; k < 100; k++) { var mid = (lo + hi) / 2; if (f(mid) > 0) lo = mid; else hi = mid; }
    return { rate: (lo + hi) / 2 };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function yearsText(months) {
    var y = Math.floor(months / 12), m = Math.floor(months - y * 12);
    return y + ' year' + (y === 1 ? '' : 's') + (m ? ' and ' + m + ' month' + (m === 1 ? '' : 's') : '');
  }

  function update() {
    var mode = document.getElementById('rxMode').value;
    document.getElementById('rxWrapSavings').hidden = mode === 'needed';
    document.getElementById('rxWrapIncome').hidden = mode === 'income';
    document.getElementById('rxWrapYears').hidden = mode === 'lasts';
    document.getElementById('rxWrapRate').hidden = mode === 'rate';
    document.getElementById('rxWrapLegacy').hidden = mode === 'lasts';
    var S = num('rxSavings'), W = num('rxIncome'), N = Math.round(num('rxYears')), r = num('rxRate'),
        g = num('rxIncrease'), tax = num('rxTax'), L = num('rxLegacy');
    var need = { savings: mode !== 'needed', income: mode !== 'income', years: mode !== 'lasts', rate: mode !== 'rate', legacy: mode !== 'lasts' };
    var error = document.getElementById('rxError');
    var bad = isNaN(g) || isNaN(tax) || g < 0 || g > 20 || tax < 0 || tax > 60 ||
              (need.savings && (isNaN(S) || S < 0)) || (need.income && (isNaN(W) || W < 0)) ||
              (need.years && (isNaN(N) || N < 1 || N > 60)) || (need.rate && (isNaN(r) || r < 0 || r > 30)) ||
              (need.legacy && (isNaN(L) || L < 0));
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, 1 to 60 years, a return up to 30%, an increase up to 20% and a tax rate up to 60%.';
      return;
    }
    if (!need.legacy) L = 0;
    r = r / 100; g = g / 100; tax = tax / 100;
    var warn = '', summary = '', sim;
    if (mode === 'income') {
      var avail = S - legacyPv(L, r, N);
      W = avail > 0 ? avail / factor(r, g, N) : 0;
      if (avail <= 0 && L > 0) warn = 'Your savings are not enough to leave that balance at the end, so no income is left to spend.';
      set('rxMainLabel', 'Monthly income'); set('rxMain', money.format(W));
      summary = 'Your savings can pay ' + money.format(W) + ' a month in the first year, rising ' + pct.format(g) +
                ' a year, for ' + N + ' years' + (L > 0 ? ', leaving ' + money.format(L) + ' at the end.' : '.');
      sim = run(S, W, r, g, N);
    } else if (mode === 'needed') {
      S = W * factor(r, g, N) + legacyPv(L, r, N);
      set('rxMainLabel', 'Savings needed'); set('rxMain', money.format(S));
      summary = 'To draw ' + money.format(W) + ' a month, rising ' + pct.format(g) + ' a year, for ' + N + ' years' +
                (L > 0 ? ' and leave ' + money.format(L) : '') + ', you need ' + money.format(S) + ' at retirement.';
      sim = run(S, W, r, g, N);
    } else if (mode === 'lasts') {
      sim = run(S, W, r, g, 100);
      set('rxMainLabel', 'Savings last');
      if (sim.months === null) {
        set('rxMain', '100+ years');
        summary = 'At this income your savings still have ' + money.format(sim.end) + ' left after 100 years.';
      } else {
        set('rxMain', yearsText(sim.months));
        summary = 'Withdrawing ' + money.format(W) + ' a month, rising ' + pct.format(g) + ' a year, your savings run out after about ' +
                  yearsText(sim.months) + '.';
      }
      N = sim.rows.length;
    } else {
      var sr = solveRate(S, W, g, N, L);
      set('rxMainLabel', 'Return needed');
      if (sr.rate === null) {
        set('rxMain', sr.high ? 'Over 100%' : 'Below -50%');
        warn = sr.high ? 'No realistic return makes these savings last. Lower the income, shorten the period or add savings.'
                       : 'Your savings cover this income even if they lose value every year.';
        sim = run(S, W, 0, g, N);
      } else {
        set('rxMain', pct.format(sr.rate));
        summary = 'You need an average return of ' + pct.format(sr.rate) + ' a year to draw ' + money.format(W) + ' a month, rising ' +
                  pct.format(g) + ' a year, for ' + N + ' years' + (L > 0 ? ' and leave ' + money.format(L) + '.' : '.');
        if (sr.rate <= 0) warn = 'Even with no investment growth your savings cover this income.';
        sim = run(S, W, sr.rate, g, N);
      }
    }
    var lastPay = sim.rows.length ? sim.rows[sim.rows.length - 1].pay : 0;
    set('rxAfterTax', money.format(W * (1 - tax)) + ' /mo');
    set('rxLast', money.format(lastPay));
    set('rxTotal', money.format(sim.total));
    set('rxSummary', summary);
    var warnEl = document.getElementById('rxWarn');
    warnEl.hidden = !warn;
    warnEl.textContent = warn;
    var body = document.getElementById('rxSchedule');
    body.textContent = '';
    sim.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.year, money.format(row.pay), money.format(row.out), money.format(row.growth), money.format(row.balance)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rxForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
